__global__ void fused_kernel(const float* x, const float* y, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = (x[idx] + y[idx]) * y[idx];
    }
}

torch::Tensor fused_op_rocm(torch::Tensor x, torch::Tensor y) {
    auto out = torch::empty_like(x);
    int size = x.numel();

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    fused_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), y.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}

