__global__ void fused_clamp_softmax_scale_kernel(
    const float* input,
    float* output,
    float clamp_min,
    float clamp_max,
    float scale,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width) {

    const int total_positions = batch_size * depth * height * width;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_positions) return;

    int w = idx % width;
    int i = idx / width;
    int h = i % height;
    i /= height;
    int d = i % depth;
    i /= depth;
    int b = i % batch_size;

    float max_val = -INFINITY;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        max_val = fmaxf(max_val, val);
    }

    float sum_exp = 0.0f;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        sum_exp += expf(val - max_val);
    }

    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        float exp_val = expf(val - max_val);
        output[input_idx] = (exp_val / sum_exp) * scale;
    }
}

torch::Tensor fused_clamp_softmax_scale_rocm(torch::Tensor input, float clamp_min, float clamp_max, float scale) {
    AT_ASSERTM(input.dim() == 5, "Input tensor must be 5D");
    auto output = torch::empty_like(input);

    int batch_size = input.size(0);
    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    int total_positions = batch_size * depth * height * width;
    const int block_size = 256;
    int num_blocks = (total_positions + block_size - 1) / block_size;

    auto stream = at::hip::getCurrentHIPStream();
    fused_clamp_softmax_scale_kernel<<<num_blocks, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        clamp_min,
        clamp_max,
        scale,
        batch_size,
        channels,
        depth,
        height,
        width
    );
    return output;
}

