#define CHECK_DEVICE(x) TORCH_CHECK(x.is_cuda(), #x " must be CUDA tensor")
#define CHECK_CONTIG(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")
#define CHECK_DIM(x,d) TORCH_CHECK(x.dim() == d, #x " must have dim " #d)

__global__ void fused_op_kernel(
    float* __restrict__ out,
    const float* __restrict__ x,
    const float* __restrict__ bias,
    const float* __restrict__ scale,
    int N, int C, int H, int W) {

    const int spatial_size = H * W;
    const int c = blockIdx.y;
    const int n = blockIdx.z;

    for(int idx = blockIdx.x * blockDim.x + threadIdx.x; 
        idx < spatial_size; 
        idx += gridDim.x * blockDim.x) {
        const int h = idx / W;
        const int w = idx % W;
        const int out_idx = ((n * C + c) * H + h) * W + w;

        float val = x[out_idx] + bias[c];
        val *= scale[c];
        out[out_idx] = 1.0f / (1.0f + expf(-val));
    }
}

torch::Tensor fused_bias_scale_sigmoid(torch::Tensor x, torch::Tensor bias, torch::Tensor scale) {
    CHECK_DEVICE(x); CHECK_DEVICE(bias); CHECK_DEVICE(scale);
    CHECK_CONTIG(x); CHECK_CONTIG(bias); CHECK_CONTIG(scale);
    CHECK_DIM(bias, 3); CHECK_DIM(scale, 3);

    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);
    auto out = torch::empty_like(x);

    const int spatial_size = H * W;
    const int threads = 256;
    const int blocks_x = (spatial_size + threads - 1) / threads;
    const dim3 blocks(blocks_x, C, N);

    hipLaunchKernelGGL(fused_op_kernel, 
        blocks, threads, 0, at::hip::getCurrentHIPStream(),
        out.data_ptr<float>(),
        x.data_ptr<float>(),
        bias.contiguous().data_ptr<float>(),
        scale.contiguous().data_ptr<float>(),
        N, C, H, W
    );

    return out;
}

